output:
variable "bucket_name" {
  type        = string
  description = "Name of the S3 bucket"
}

resource "aws_s3_bucket" "assets" {
  bucket = var.bucket_name

  tags = {
    Name = var.bucket_name
  }
}

output "bucket_name" {
  value = aws_s3_bucket.assets.id
}

variable "instance_type" {
  type    = string
  default = "t3.micro"
}

variable "ami_id" {
  type = string
}

resource "aws_instance" "web" {
  ami           = var.ami_id
  instance_type = var.instance_type

  tags = {
    Name = "web-server"
  }
}

locals {
  common_tags = {
    Project     = "acme"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

resource "aws_sns_topic" "alerts" {
  name = "acme-alerts"
  tags = local.common_tags
}

terraform {
  required_providers {
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

resource "random_password" "db" {
  length  = 24
  special = true
}

output "db_password" {
  value     = random_password.db.result
  sensitive = true
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

resource "aws_sqs_queue" "jobs" {
  name                       = "worker-jobs"
  visibility_timeout_seconds = 60
}

variable "azs" {
  type = list(string)
  default = [
    "us-east-1a",
    "us-east-1b",
  ]
}

locals {
  az_names = join(", ", var.azs)
}

output "availability_zones" {
  value = local.az_names
}

variable "app_config" {
  type = object({
    log_level = string
    workers   = number
  })
  default = {
    log_level = "info"
    workers   = 2
  }
}

resource "aws_lambda_function" "processor" {
  function_name = "processor"
  role          = var.execution_role_arn
  handler       = "index.handler"
  runtime       = "python3.12"
  filename      = "function.zip"

  environment {
    variables = {
      LOG_LEVEL = var.app_config.log_level
      WORKERS   = tostring(var.app_config.workers)
    }
  }
}

variable "execution_role_arn" {
  type = string
}

resource "aws_sqs_queue" "dead_letter" {
  name = "orders-dead-letter"
}

output "dead_letter_queue_arn" {
  description = "ARN of the dead letter queue"
  value       = aws_sqs_queue.dead_letter.arn
}

variable "project" {
  type = string
}

variable "environment" {
  type = string
}

locals {
  name_prefix = "${var.project}-${var.environment}"
}

resource "aws_cloudwatch_log_group" "app" {
  name              = "/aws/lambda/${local.name_prefix}"
  retention_in_days = 14
}

terraform {
  required_providers {
    random = {
      source = "hashicorp/random"
    }
  }
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_sqs_queue" "events" {
  name = "events-${random_id.suffix.hex}"
}

variable "notification_protocol" {
  type = string
  default = "email"
}

variable "notification_endpoint" {
  type = string
}

resource "aws_sns_topic" "releases" {
  name = "release-announcements"
}

resource "aws_sns_topic_subscription" "team" {
  topic_arn = aws_sns_topic.releases.arn
  protocol  = var.notification_protocol
  endpoint  = var.notification_endpoint
}

variable "log_retention_days" {
  type    = number
  default = 30
}

resource "aws_cloudwatch_log_group" "ingest" {
  name              = "/acme/ingest"
  retention_in_days = var.log_retention_days
}

resource "aws_dynamodb_table" "sessions" {
  name         = "sessions"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "session_id"

  attribute {
    name = "session_id"
    type = "S"
  }

  tags = {
    Name      = "sessions"
    Component = "auth"
  }
}

variable "extra_tags" {
  type    = map(string)
  default = {}
}

resource "aws_sqs_queue" "emails" {
  name = "email-outbox"

  tags = merge(var.extra_tags, {
    ManagedBy = "terraform"
  })
}

terraform {
  required_version = ">= 1.5.0"
}

variable "queue_name" {
  type = string
}

resource "aws_sqs_queue" "main" {
  name = var.queue_name
}

variable "lambda_runtime" {
  type    = string
  default = "python3.12"
}

variable "lambda_handler" {
  type    = string
  default = "app.handler"
}

resource "aws_lambda_function" "api" {
  function_name = "api-handler"
  filename      = "deploy.zip"
  role          = var.lambda_role_arn
  runtime       = var.lambda_runtime
  handler       = var.lambda_handler
}

variable "lambda_role_arn" {
  type = string
}

locals {
  env        = "staging"
  owner      = "platform-team"
  cost_center = "cc-4412"
}

output "stack_metadata" {
  value = {
    environment = local.env
    owner       = local.owner
    cost_center = local.cost_center
  }
}

resource "aws_sqs_queue" "ingest" {
  name = "ingest-queue"
}

resource "aws_sqs_queue_policy" "ingest" {
  queue_url = aws_sqs_queue.ingest.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAccountSend"
        Effect    = "Allow"
        Principal = { AWS = "*" }
        Action    = "sqs:SendMessage"
        Resource  = aws_sqs_queue.ingest.arn
        Condition = {
          StringEquals = {
            "aws:PrincipalAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

terraform {
  required_providers {
    random = {
      source = "hashicorp/random"
    }
  }
}

resource "random_pet" "name" {
  length = 2
}

resource "aws_s3_bucket" "scratch" {
  bucket = "scratch-${random_pet.name.id}"
}

variable "name" {
  type = string
}

locals {
  env      = terraform.workspace == "default" ? "dev" : terraform.workspace
  full_name = "${var.name}-${local.env}"
}

resource "aws_sqs_queue" "stack" {
  name = local.full_name
}

output "queue_url" {
  value = aws_sqs_queue.stack.url
}
